#!/usr/bin/env node
// Copyright (c) Cesteral AB. Licensed under the Apache License, Version 2.0.
//
// Scaffold smoke: proves a server generated by `pnpm new:server` passes the
// fleet's checks, except the wire-request coverage of its four write stubs
// (expected-todo.mjs). Any other failure, or that one going missing, fails.
//
// It works in a throwaway `git worktree` of HEAD, so it never touches the
// checkout it runs from, and always removes the worktree.
//
//   node scripts/scaffold/smoke.mjs [--variant read-only | journey]
//
// Set PNPM to override the pnpm command (e.g. PNPM="npx -y pnpm@10.34.5" where
// the global pnpm is too old).

import { execSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { pathToFileURL } from "node:url";
import { expectedTodoFailures, expectedTodoTools } from "./expected-todo.mjs";
import { failuresFromReport } from "./report.mjs";
import { DEPLOY_SITE_FILES } from "../lib/fleet-inventory.mjs";

const ROOT = join(import.meta.dirname, "../..");
const KEY = "zzscaffold";
const PACKAGE = "zzscaffold-mcp";
const PNPM = process.env.PNPM ?? "pnpm";

/**
 * read-only: the default scaffold, which must pass with no failure at all and
 * stay out of the deploy lists. journey: the same scaffold, then
 * `--add-write-stubs` and `promote:server`; only the stubs' wire-request
 * coverage may fail, and the deploy lists must name the server.
 */
const VARIANTS = ["read-only", "journey"];
const variantArg = process.argv.indexOf("--variant");
const VARIANT = variantArg > 0 ? process.argv[variantArg + 1] : "read-only";
const WRITES = VARIANT === "journey";

function run(cmd, cwd) {
  console.log(`\n$ ${cmd}`);
  execSync(cmd, { cwd, stdio: "inherit", env: { ...process.env, CI: process.env.CI ?? "1" } });
}

/** Failed tests (and files that never ran their tests) from a vitest JSON report. */
function failures(reportPath, tree) {
  const report = JSON.parse(readFileSync(reportPath, "utf8"));
  for (const file of report.testResults) file.name = relative(tree, file.name);
  return failuresFromReport(report);
}

/**
 * The generated server's write tools that no wire-request test covers,
 * computed with the tree's own coverage library (vitest truncates the
 * assertion message, so the failure text cannot be relied on to list them).
 */
async function uncoveredWrites(tree) {
  const lib = (p) => import(pathToFileURL(join(tree, "scripts/lib", p)).href);
  const { withServerClient, listRawTools } = await lib("boot-server.mjs");
  const { coveredTools } = await lib("wire-request-coverage.mjs");
  const tools = await withServerClient(PACKAGE, listRawTools);
  const writes = tools.filter((t) => t.annotations?.readOnlyHint === false).map((t) => t.name);
  const covered = coveredTools(PACKAGE, writes);
  return writes.filter((name) => !covered.has(name)).sort();
}

function compare(failed) {
  const expected = new Set(expectedTodoFailures(KEY, { writes: WRITES }));
  const unexpected = [...failed.keys()].filter((n) => !expected.has(n));
  const missing = [...expected].filter((n) => !failed.has(n));
  const problems = [];
  for (const name of unexpected) problems.push(`unexpected failure: ${name}\n${failed.get(name)}`);
  for (const name of missing) {
    problems.push(
      `missing expected failure (a stub is now covered? update expected-todo.mjs): ${name}`
    );
  }
  return { problems, expected: expected.size };
}

async function main() {
  if (!VARIANTS.includes(VARIANT)) {
    console.error(`usage: smoke.mjs [--variant ${VARIANTS.join(" | ")}]`);
    return 2;
  }
  console.log(`scaffold smoke: ${VARIANT}`);
  const tmp = mkdtempSync(join(tmpdir(), "scaffold-smoke-"));
  const tree = join(tmp, "repo");
  run(`git worktree add --detach "${tree}" HEAD`, ROOT);
  try {
    // A contributor has installed before running new:server; the second
    // install links the new package into the workspace.
    run(`${PNPM} install --frozen-lockfile`, tree);
    run(
      `node scripts/new-server.mjs ${KEY} --display-name "ZZ Scaffold" ` +
        `--base-url https://api.example.invalid/v1 --docs-url https://docs.example.invalid`,
      tree
    );
    if (WRITES) {
      run(`node scripts/new-server.mjs ${KEY} --add-write-stubs`, tree);
      run(`node scripts/promote-server.mjs ${KEY}`, tree);
    }
    run(`${PNPM} install --no-frozen-lockfile`, tree);
    run(`${PNPM} run build`, tree);
    // Generated from the built servers; the CLI prints it as a next step.
    run(`${PNPM} run sync:untrusted-declarations`, tree);
    // Build-and-test runs these against the built servers too.
    run(`${PNPM} run generate:manifests`, tree);
    run(`${PNPM} run check:registry-runtime`, tree);
    for (const script of [
      "format:check",
      "generate:registry",
      "check:registry",
      "check:registry-tools",
      "check:doc-tool-counts",
      "check:account-scope",
      "check:platform-facts",
    ]) {
      run(`${PNPM} run ${script}`, tree);
    }
    run(`${PNPM} --filter @cesteral/${PACKAGE} run lint`, tree);
    // Every package's tests, @cesteral/shared's included: its resolver-coverage
    // and testkit suites read the registry entry the scaffold wrote.
    run(`${PNPM} run test`, tree);
    const deployLists = DEPLOY_SITE_FILES.filter((f) =>
      readFileSync(join(tree, f), "utf8").includes(PACKAGE)
    );
    const wantLists = WRITES ? DEPLOY_SITE_FILES : [];
    if (JSON.stringify(deployLists) !== JSON.stringify(wantLists)) {
      throw new Error(
        `${PACKAGE} is in deploy lists [${deployLists.join(", ")}], expected [${wantLists.join(", ")}]`
      );
    }

    const report = join(tmp, "r.json");
    try {
      run(
        `./node_modules/.bin/vitest run --config vitest.config.scripts.ts ` +
          `--reporter=default --reporter=json --outputFile.json="${report}" ` +
          // The scaffold's own unit tests assume the unscaffolded repo (next
          // free port, no zzscaffold entry); the test-scripts job runs them.
          `--exclude "scripts/scaffold/**"`,
        tree
      );
    } catch (err) {
      // Failures are expected; the report decides. A run that wrote no
      // report (a crash, a signal) is not a result.
      if (!existsSync(report)) {
        throw new Error(
          `the scripts suite wrote no report (exit ${err.status}, signal ${err.signal ?? "none"})`
        );
      }
    }
    const failed = failures(report, tree);
    const { problems, expected } = compare(failed);
    if (problems.length) {
      console.error(`\nscaffold smoke FAILED:\n\n${problems.join("\n\n")}`);
      return 1;
    }
    const uncovered = await uncoveredWrites(tree);
    const want = [...expectedTodoTools(KEY, { writes: WRITES })].sort();
    if (JSON.stringify(uncovered) !== JSON.stringify(want)) {
      console.error(
        `\nscaffold smoke FAILED: uncovered write tools are [${uncovered.join(", ")}], ` +
          `expected exactly [${want.join(", ")}]`
      );
      return 1;
    }
    console.log(
      `\nscripts suite: failed = expected (${expected}); uncovered writes = the ${want.length} stubs`
    );

    run(`bash scripts/conformance-test.sh --ci ${PACKAGE}`, tree);
    console.log("\nscaffold smoke passed");
    return 0;
  } catch (err) {
    console.error(`\nscaffold smoke FAILED: ${err.message}`);
    return 1;
  } finally {
    try {
      execSync(`git worktree remove --force "${tree}"`, { cwd: ROOT, stdio: "inherit" });
    } finally {
      rmSync(tmp, { recursive: true, force: true });
    }
  }
}

process.exitCode = await main();
